def extract_faqs_strict(html_text):
    faqs = []
    m = re.search(r'<h2>پرسش‌های متداول.*?</h2>(.*?)<h2>منابع', html_text, re.DOTALL)
    if m:
        content = m.group(1)
        items = re.findall(r'<h3>(.*?)</h3>\s*<p>(.*?)</p>', content, re.DOTALL)
        for q, a in items:
            q_clean = re.sub(r'<.*?>', '', q).strip()
            a_clean = re.sub(r'<.*?>', '', a).strip()
            faqs.append({'question': q_clean, 'answer': a_clean})
    return faqs

def count_words(text):
    clean = re.sub(r'<.*?>', ' ', text)
    return len(clean.split())

for art in ARTICLES:
    seq = art['seq']
    slug = art['slug']
    folder_name = f"{seq}-{slug}"
    target_dir = ART_DIR / folder_name
    target_dir.mkdir(parents=True, exist_ok=True)
    
    html_content = art['content'].strip()
    faqs = extract_faqs_strict(html_content)
    words = count_words(html_content)
    
    # Internal links count
    internal_links = re.findall(r'href="(/[^"]+/)"', html_content)
    
    print(f"Building [{seq}] {slug}: {words} words, {len(internal_links)} internal links, {len(faqs)} FAQs")
    assert len(internal_links) >= 5, f"Article {slug} has less than 5 internal links ({len(internal_links)})"
    assert len(faqs) >= 3, f"Article {slug} has less than 3 FAQs ({len(faqs)})"
    assert words >= 800, f"Article {slug} has less than 800 words ({words})"
    
    # Write article.html
    (target_dir / 'article.html').write_text(html_content + '\n', encoding='utf-8')
    
    # Write metadata.json
    metadata = {
        'sequence': int(seq),
        'post_id': None,
        'slug': slug,
        'title': art['h1'],
        'h1': art['h1'],
        'seo_title': art['seo_title'],
        'meta_description': art['meta_desc'],
        'focus_keyword': art['focus_kw'],
        'category': art['category'],
        'date': art['date'],
        'modified': art['modified'],
        'word_count': words,
        'internal_links_count': len(internal_links),
        'internal_links': internal_links,
        'analogy_concept': art['analogy_concept'],
        'analogy_breakdown': art['analogy_breakdown']
    }
    (target_dir / 'metadata.json').write_text(json.dumps(metadata, ensure_ascii=False, indent=2), encoding='utf-8')
    
    # Write schema.json
    schema = {
        "@context": "https://schema.org",
        "@type": "Article",
        "headline": art['h1'],
        "name": art['seo_title'],
        "description": art['meta_desc'],
        "datePublished": art['date'],
        "dateModified": art['modified'],
        "mainEntityOfPage": {
            "@type": "WebPage",
            "@id": f"https://qpedia.org/{slug}/"
        },
        "publisher": {
            "@type": "Organization",
            "name": "Qpedia",
            "url": "https://qpedia.org"
        }
    }
    if faqs:
        faq_entities = []
        for f in faqs:
            faq_entities.append({
                "@type": "Question",
                "name": f['question'],
                "acceptedAnswer": {
                    "@type": "Answer",
                    "text": f['answer']
                }
            })
        schema['mainEntity'] = {
            "@type": "FAQPage",
            "mainEntity": faq_entities
        }
    (target_dir / 'schema.json').write_text(json.dumps(schema, ensure_ascii=False, indent=2), encoding='utf-8')

print("All 5 special articles built, validated, and saved successfully!")
